#nullable enable // autogenerated

using MVZ2.GameContent.Buffs.Contraptions;
using PVZEngine.Buffs;
using PVZEngine.Callbacks;
using PVZEngine.Definitions;
using PVZEngine.Entities;

namespace MVZ2.GameContent.Buffs.Level
{
    [AutoBuffDefinition(VanillaBuffNames.Level.withersSkull)]
    public class WithersSkullBuff : CurseBuffDefinition
    {
        public WithersSkullBuff(string nsp, string name) : base(nsp, name)
        {
            AddTriggerFiltered(LevelCallbacks.POST_ENTITY_INIT, PostContraptionInitCallback, EntityTypes.PLANT);
        }
        private void PostContraptionInitCallback(EntityCallbackParams args, CallbackResultVoid result)
        {
            var entity = args.entity;
            if (!entity.Level.HasBuff(this))
                return;
            entity.AddBuff<WithersSkullForContraptionBuff>();
        }
    }
}
